Fix /app/frontend/src/components/SocialShareRow.jsx::ShareIconLink to consume the `targetBlank` prop and conditionally render target. Suggested patch:
  function ShareIconLink({ href, label, testId, platformClass, children, targetBlank = true }) {
    return (
      <a href={href} {...(targetBlank ? { target: '_blank', rel: 'noopener noreferrer' } : {})} aria-label={label} ... />
    );
  }
Then retest [data-testid='share-view-social-email'] has no target attribute (or target!=='_blank').
